{"ASK_SAFE_PLACE","reg=civilian,family|tmp=fresh|st=friendly,neutral|day=0,7",{"People say the school's taking folks in, I don't know, I just didn't want to be in a crowd"}},
{"ASK_SAFE_PLACE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|world=window",{"Pick a house with a fenced yard and no broken glass - board the bottom floor - sleep up top"}},
