{"ASK_SAFE_PLACE","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral",{"Don't hole up in a store, everybody in the county knows where the stores are"}},
{"ASK_SAFE_PLACE","reg=worker|st=friendly,neutral|world=door",{"Our break room at the warehouse has a steel door and a lock only we have keys to - it's full up, though - sorry"}},
{"ASK_SAFE_PLACE","reg=worker|st=friendly,neutral|world=stairs,building",{"Get on a roof with a ladder you can pull up after you - did it three nights with the roofing crew"}},
